/**
 * Artwork for the brand cover (quotation and datasheet), taken from the
 * approved Quotation_Cover_Template.pptx (ppt/media) and re-encoded smaller
 * (the photo as a JPEG, the QR codes as 1-bit PNGs flattened onto white);
 * the quotation's hero is drawn for Art Lighting and stored as a JPEG.
 * Base64-in-TS because the serverless routes that build the documents have
 * no reliable filesystem path to read assets from, and a string in a module
 * resolves identically in Next.js (admin) and plain tsx (the worker).
 */

type CoverImage = { dataUri: string; width: number; height: number };

export const BRAND_COVER: Record<"hero" | "photo" | "logo" | "qrWebsite" | "qrLocation" | "balcom" | "misterLed", CoverImage> = {
  /**
   * Flowing gold light-wave lines around a soft warm glow, on the page
   * colour; its lower edge already fades into the page. Rendered at 2.5 px/pt.
   */
  hero: {
    width: 1489,
    height: 1205,
    dataUri:
      "data:image/jpeg;base64,",
  },
  /** The template's night photograph of a lit façade and street poles, for the datasheet cover; its lower edge already fades into the page colour. */
  photo: {
    width: 1488,
    height: 1205,
    dataUri:
      "data:image/jpeg;base64,",
  },
  /** The round gold Art Lighting badge. */
  logo: {
    width: 238,
    height: 240,
    dataUri:
      "data:image/png;base64,",
  },
  /** QR code to artlighting-eg.com, black on white. */
  qrWebsite: {
    width: 512,
    height: 512,
    dataUri:
      "data:image/png;base64,",
  },
  /** QR code to the showroom location, black on white. */
  qrLocation: {
    width: 512,
    height: 512,
    dataUri:
      "data:image/png;base64,",
  },
  /** Balcom wordmark, white, for the dark page. */
  balcom: {
    width: 300,
    height: 300,
    dataUri:
      "data:image/png;base64,",
  },
  /** Mister LED wordmark, white, for the dark page. */
  misterLed: {
    width: 300,
    height: 300,
    dataUri:
      "data:image/png;base64,",
  },
};
